class _WavePainter extends CustomPainter { const _WavePainter(this.color); final Color color; @override void paint(Canvas canvas,Size size){final path=Path()..moveTo(0,size.height*.72)..cubicTo(size.width*.2,size.height*.12,size.width*.42,size.height*.85,size.width*.6,size.height*.3)..cubicTo(size.width*.78,0,size.width*.86,size.height*.82,size.width,size.height*.22);canvas.drawPath(path,Paint()..color=color..style=PaintingStyle.stroke..strokeWidth=3);}@override bool shouldRepaint(_WavePainter old)=>old.color!=color;}
